export type ShapeType = 'actor' | 'system' | 'app' | 'store' | 'component' | 'group'
export type Compatibility = ShapeType | 'all'

export interface IconDefinition {
  name: string
  bg: string
  text: string
  abbr: string
  packs: string[]
  compatibleWith: Compatibility[]
  iconLight?: string
  iconDark?: string
  warning?: string
  info?: string
  framework?: string[]
  protocol?: string[]
}

