// The generated catalog historically embedded the development nginx origin in
// every entry. Normalize once at module load: production nginx and Vite's dev
// proxy now expose the exact same, mixed-content-safe URL namespace.
for (const icon of ICONS) {
  if (icon.iconLight?.startsWith(LEGACY_ICON_BASE_URL)) {
    icon.iconLight = icon.iconLight.replace(LEGACY_ICON_BASE_URL, ICON_BASE_URL)
  }
  if (icon.iconDark?.startsWith(LEGACY_ICON_BASE_URL)) {
    icon.iconDark = icon.iconDark.replace(LEGACY_ICON_BASE_URL, ICON_BASE_URL)
  }
}

export const TECH_ICON_NAMES = ICONS.map((i) => i.name)

export function getPacks(): string[] {
  const packs = new Set<string>()
  packs.add('All')
  ICONS.forEach((icon) => {
    icon.packs.forEach((p) => {
      if (p !== 'All') packs.add(p)
    })
  })
  return Array.from(packs).sort((a, b) => {
    if (a === 'All') return -1
    if (b === 'All') return 1
    return a.localeCompare(b)
  })
}

export function filterIcons(search: string, pack: string): IconDefinition[] {
  const s = search.toLowerCase()
  return ICONS.filter((icon) => {
    const matchesSearch = !s || icon.name.toLowerCase().includes(s)
    const matchesPack = pack === 'All' || icon.packs.includes(pack)
    return matchesSearch && matchesPack
  })
}

export function getCompatibilityWarning(
  icon: IconDefinition,
  shapeType: ShapeType
): string | null {
  if (icon.compatibleWith.includes('all')) return null
  if (!icon.compatibleWith.includes(shapeType)) {
    const allowed = icon.compatibleWith.join(', ')
    return `Recommended for: ${allowed}`
  }
  return null
}

// Lazily-built name → icon index. Building it once turns getIconByName from an
// O(ICONS) linear scan (~3000 entries) into an O(1) lookup — it is called per
// rendered row in icon-heavy lists (TechIconBadge), so the scan was a hotspot.
let iconByName: Map<string, IconDefinition> | null = null

// The governed starter catalog uses canonical product names while the visual
// catalog preserves upstream icon-pack labels. Keep that naming bridge here;
// it selects artwork only and never leaks visual compatibility into technology
// governance.
const TECHNOLOGY_ICON_ALIASES: Readonly<Record<string, string>> = {
  'Azure Blob': 'Azure Blob Storage',
  'C#': 'C# (Sharp)',
  'C++': 'C++ (PlusPlus)',
  Cassandra: 'Apache Cassandra',
  DynamoDB: 'Amazon DynamoDB',
  Elasticsearch: 'Elastic Search',
  Flink: 'Apache Flink',
  Go: 'Golang',
  nginx: 'NGINX',
  'Node.js': 'NodeJS',
  REST: 'REST (Representational State Transfer)',
  S3: 'Amazon Simple Storage Service Bucket',
  Spark: 'Apache Spark',
  Terraform: 'HashiCorp Terraform',
  Vue: 'Vue.js',
}

export function getIconByName(name: string): IconDefinition | undefined {
  if (!iconByName) {
    iconByName = new Map()
    // First occurrence wins, matching the previous ICONS.find() semantics.
    for (const i of ICONS) if (!iconByName.has(i.name)) iconByName.set(i.name, i)
  }
  return iconByName.get(name) ?? iconByName.get(TECHNOLOGY_ICON_ALIASES[name] ?? '')
}

// Metadata for well-known technology icons — used to auto-fill framework/protocol
const TECH_METADATA: Record<string, { framework?: string[]; protocol?: string[] }> = {
  'React': { framework: ['React'] },
  'Node.js': { framework: ['Node.js'] },
  'Go': { framework: ['Go'] },
  'Socket.io': { protocol: ['WebSocket', 'Socket.IO'] },
  'PostgreSQL': { protocol: ['SQL', 'PostgreSQL'] },
  'Firebase Auth': { framework: ['Firebase'] },
  'S3': { protocol: ['S3', 'REST'] },
  'Pub/Sub': { protocol: ['Pub/Sub', 'gRPC'] },
  'Cloud Scheduler': { framework: ['GCP'] },
  'Redis': { protocol: ['Redis'] },
  'Firebase': { framework: ['Firebase'] },
  'Azure Service Fabric': { framework: ['Azure', '.NET'] },
  'AWS Systems Manager State Manager': { framework: ['AWS'] },
  'Amazon EC2 Spot Instance': { framework: ['AWS'] },
}

export function getTechMetadata(name: string): { framework?: string[]; protocol?: string[] } {
  const icon = getIconByName(name)
  const meta = TECH_METADATA[name]
  return {
    framework: icon?.framework ?? meta?.framework,
    protocol: icon?.protocol ?? meta?.protocol,
  }
}
